entries[44502] = { ["name"] = "Bauplan: Feuerstuhl", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (450)\nBenötigt Expedition der Horde\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung eines Feuerstuhls.\nVerkaufspreis:\nFeuerstuhl\nReittier\nBenötigt eine Horde-Rasse\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man diesen heißen Ofen fährt.\nBeschwört einen echt heißen Ofen oder parkt ihn.\nVerkaufspreis:\nBenötigt Titanstahlbarren (12), Eine Hand voll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44503] = { ["name"] = "Bauplan: Chopper des Robogenieurs", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Ingenieurskunst (450)\nBenötigt Vorposten der Allianz\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Chopper des Robogenieurs.\nVerkaufspreis:\nChopper des Robogenieurs\nReittier\nBenötigt eine Allianz-Rasse\nBenötigt Stufe 40\nBenötigt Geübtes Reiten\nBenutzen: Lehrt Euch, wie man diesen Chopper fährt.\nBeschwört einen echt fetten Chopper des Robogenieurs oder parkt ihn.\nBenötigt Titanstahlbarren (12), Eine Hand voll Kobaltbolzen (40), Arktischer Pelz (2), Geborgene Dunkeleisenteile , Goblinmaschinenkolben (8), Elementiumveredelter Auspuff" }
entries[44504] = { ["name"] = "Nesingwary 4000", ["text"] = "Wird beim Anlegen gebunden\nDistanz Schusswaffe\n365 - 679 Schaden Tempo 2.80\n(186.43 Schaden pro Sekunde)\n+39 Beweglichkeit\n\nGelber Sockel\nSockelbonus: +8 Angriffskraft\n\nHaltbarkeit 90 / 90\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 21.\nVerkaufspreis:" }
