entries[44554] = { ["name"] = "Fliegender Teppich", ["text"] = "Reittier\nBenötigt Stufe 60\nBenötigt Schneiderei (300)\nBenötigt Erfahrenes Reiten\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen fliegenden Teppich oder gibt ihn wieder frei. Die Nutzung benötigt eine Schneiderfertigkeit von 300. Dieser Teppich passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an." }
