entries[44584] = { ["name"] = "Muster: Polarweste", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (425)\nBenutzen: Lehrt Euch die Herstellung einer Polarweste.\n\nPolarweste\nWird beim Anlegen gebunden\nBrust Leder\n1145 Rüstung\n+169 Ausdauer\n+115 Frostwiderstand\n\nRoter Sockel\nGelber Sockel\nBlauer Sockel\nSockelbonus: +12 Ausdauer\n\nHaltbarkeit 165 / 165\nBenötigt Stufe 80\nVerkaufspreis:\nBenötigt Schweres boreanisches Leder (10), Äonenfeuer (3), Äonenwasser (3), Nerubisches Chitin (8), Gefrorene Kugel" }
