entries[44598] = { ["name"] = "Schrapnellgranate", ["text"] = "Benötigt Ingenieurskunst (375)\nBenutzen: Fügt Feinden 75 to 125 Frostschaden zu und friert sie 5 Sek. lang fest. Verursachter Schaden kann den Effekt unterbrechen. (1 Min Abklingzeit)\nVerkaufspreis:" }
