entries[44600] = { ["name"] = "Foliant der Verwandlung: Schlange", ["text"] = "Klassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt Euch 'Verwandlung: Schlange'.\nVerwandelt den Feind in eine harmlose Schlange und zwingt ihn, 50 Sek. lang so herumzukriechen. Während die Schlange herumkriecht, kann sie weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren.\nVerkaufspreis:" }
entries[44601] = { ["name"] = "Schwerer Kupferflitzer", ["text"] = "Benutzen: Stellt sicher, dass Ihr 20 Meter freie Rennfläche habt! (20 Sek. Abklingzeit)\n\"Fühlt Ihr den Rausch der Geschwindigkeit?\"\nVerkaufspreis:" }
entries[44602] = { ["name"] = "Foliant des Dalaranintellekts", ["text"] = "Klassen: Magier\nBenötigt Stufe 80\nBenutzen: Lehrt Euch 'Arkane Brillanz' im Stil Dalarans.\nErfüllt das Ziel mit Brillanz, welche sein maximales Mana um 600 und seine Zaubermacht um 6 % erhöht. Hält 1 Stunde lang an. Wenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten.\nVerkaufspreis:" }
