entries[44791] = { ["name"] = "Nobelgartenschokolade", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Nobelgartenfest\nBenutzen: Stellt im Verlauf von 24 Sek. pro Sekunde 2% Eurer Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Ausdauer und Willenskraft wird 15 Min. lang erhöht." }
entries[44792] = { ["name"] = "Blühender Zweig", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verkleidet ein Gruppenmitglied als Hase.\n5 Aufladungen" }
entries[44793] = { ["name"] = "Foliant der Verwandlung: Hase", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt Verwandlung: Hase.\nVerwandelt den Feind in einen harmlosen Hasen und zwingt ihn, 50 Sek. lang so herumzuhoppeln. Während der Hase herumwandert, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[44794] = { ["name"] = "Frühlingshasenpfote", ["text"] = "Benutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Euren Frühlingshasen beschwören oder wieder freigeben." }
