entries[44811] = { ["name"] = "Foliant der Verwandlung: Truthahn", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Magier\nBenötigt Stufe 60\nBenutzen: Lehrt 'Verwandlung: Truthahn'.\nVerwandelt den Feind in einen harmlosen Truthahn und zwingt ihn, 50 Sek. lang so herumzuwandern. Während der Truthahn herumwandert, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden verwandelt das Ziel in seine normale Gestalt zurück. Es kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren.\nVerkaufspreis:" }
entries[44812] = { ["name"] = "Truthahnbüchse", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Pilgerfreudenfest\nBenutzen: Bedeckt das Ziel mit Truthahnfedern." }
