entries[44851] = { ["name"] = "Erntedankfestkochbuch", ["text"] = "Benötigt Kochkunst (1)\nBenutzen: Lehrt Euch, wie man verschiedene leckere Gerichte zubereitet.\nVerkaufspreis:\nScharfe Wolfrippchen\nBenötigt Stufe 25\nBenutzen: Stellt im Verlauf von 27 Sek. 874.8 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 8 Ausdauer und Willenskraft.\nVerkaufspreis:\nBenötigt Rotes Wolfsfleisch" }
