entries[44857] = { ["name"] = "Schwarzes Drachenfalkenreittier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 70\nBenötigt Reiten (300)\n\"Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein sehr schnelles Reittier.\"" }
entries[44858] = { ["name"] = "Rezept: Moosbeerenchutney", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (160)\nBenutzen: Lehrt Euch, wie man Moosbeerenchutney zubereitet.\n\nMoosbeerenchutney\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Zaubermacht um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.6616) + 4] und Eure Ausdauer um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Säuerliche Sumpfmoosbeeren , Honig", ["unresolvedValues"] = true }
entries[44859] = { ["name"] = "Rezept: Kandierte Süßkartoffel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (220)\nBenutzen: Lehrt Euch, wie man kandierte Süßkartoffeln zubereitet.\n\nKandierte Süßkartoffel\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und Eure Tempowertung und Ausdauer wird 1 Stunde lang um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.8) + 4] erhöht.\nVerkaufspreis:\nBenötigt Süßkartoffel von Teldrassil , Honig , Herbstliche Gewürze", ["unresolvedValues"] = true }
