entries[44861] = { ["name"] = "Rezept: Langsam gerösteter Truthahn", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (280)\nBenutzen: Lehrt Euch, wie man langsam gerösteten Truthahn zubereitet.\n\nLangsam gerösteter Truthahn\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Angriffskraft um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 1.108) + 8] und Eure Ausdauer um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Wilder Truthahn , Honig (2), Herbstliche Gewürze", ["unresolvedValues"] = true }
entries[44862] = { ["name"] = "Rezept: Kürbiskuchen", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Kochkunst (100)\nBenutzen: Lehrt Euch, wie man Kürbiskuchen backt.\n\nKürbiskuchen\nBenötigt Pilgerfreudenfest\nBenutzen: Stellt im Verlauf von 30 Sek. pro Sekunde 4% Gesundheit und Mana wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sekunden lang mit Essen verbringt, werdet Ihr satt und 1 Stunde lang Eure Willenskraft und Ausdauer um [floor(cond([Quellwert]( 85, 15), 85 - 15, 0) * 0.554) + 4] erhöht.\nVerkaufspreis:\nBenötigt Reifer Elwynnkürbis , Honig", ["unresolvedValues"] = true }
