entries[44932] = { ["name"] = "Muster: Windreißerstiefel", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Lederverarbeitung (440)\nBenutzen: Lehrt Euch die Herstellung von Windreißerstiefeln.\n\nWindreißerstiefel\nWird beim Anlegen gebunden\nFüße Leder\n757 Rüstung\n+97 Ausdauer\n+66 Intelligenz\nHaltbarkeit 75 / 75\nBenötigt Stufe 80\nAnlegen: Erhöht die kritische Trefferwertung um 66.\nVerkaufspreis:\nBenötigt Schweres boreanisches Leder (10), Äonenluft (5), Äonenwasser (5), Gefrorene Kugel" }
