entries[44936] = { ["name"] = "Titanbeschlag", ["text"] = "Benötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an. Er erhöht die Parierwertung um 26 und verringert die Dauer von Entwaffnungseffekten um 60%. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird der Gegenstand seelengebunden.\nVerkaufspreis:" }
entries[44937] = { ["name"] = "Pläne: Titanbeschlag", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Schmiedekunst (450)\nBenötigt Vorposten der Allianz\n- Ehrfürchtig\nBenutzen: Lehrt Euch die Herstellung einer Titanpanzerung.\n\nTitanbeschlag\nBenötigt Stufe 70\nBenutzen: Bringt dauerhaft einen leichten Titanbeschlag an einem Schild an. Er erhöht die Parierwertung um 26 und verringert die Dauer von Entwaffnungseffekten um 60%. Ist nicht mit ähnlichen Effekten stapelbar.\n\nDurch das Anbringen des Titanbeschlags wird der Gegenstand seelengebunden.\nVerkaufspreis:\nBenötigt Titanbarren (4), Äonenschatten (4)" }
