entries[44939] = { ["name"] = "Geringes Fläschchen des Widerstands", ["text"] = "Benötigt Stufe 70\nBenutzen: Erhöht Euren Widerstand gegen alle Arten von Magie 1 Stunde lang um 50. Gilt sowohl als Kampfelixier als auch als Wächterelixier. Der Effekt hält auch nach dem Tode an. (3 Sek. Abklingzeit)\nVerkaufspreis:" }
